import{_ as l,l as n,o as e,c as o,v as r,p as E,x as t,d as s,i as B,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"盘口不平衡","description":"","frontmatter":{"title":"盘口不平衡","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/order-imbalance.md","filePath":"quant/order-imbalance.md","lastUpdated":1789023840000}'),p={name:"quant/order-imbalance.md"};function h(c,a,_,A,u,m){const i=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="盘口不平衡" tabindex="-1">盘口不平衡 <a class="header-anchor" href="#盘口不平衡" aria-label="Permalink to &quot;盘口不平衡&quot;">​</a></h1><div class="epigraph"><p>簿两侧的量若持续不对称，下一步更可能发生的是价格向薄的一侧移动——不是因为有一条外生的需求曲线在平移，而是因为可见深度与即将到来的主动单在抢同一条优先队列。</p><footer>—— 据 Harris, Trading and Exchanges 对深度、订单流与价格压力的论述整理</footer></div><p><a href="/quant/cancel-queue-position">上一课</a>把同一档拆成了队列名次。本课把两侧的量差收成一个标量。盘口不平衡不是成交方向的简单计数，也还不是后面信息模型里的充分统计量；它是对 BBO 附近深度的一种读法。存量看此刻簿上的量，流量看一段 <a href="/quant/event-time">事件时间</a> 窗口。本课先锁定价位范围和归一，下一课才把价差拆成处理、存货与逆向选择。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/quant/lob-structure">LOB</a> 的中间价 \\(m=(b_1+a_1)/2\\) 把两侧对称看待。若最优买量远大于最优卖量，对称就不再可信：同样一笔随机的主动单，打穿卖档比打穿买档容易，中间价更可能上移。缺口是如何把这种不对称写成对后续收益仍有内容、又不把存量深度与流量成交混成一个符号。</p><p>至少有两种完全不同的「不平衡」。存量不平衡看此刻簿上的量：\\((q^b-q^a)/(q^b+q^a)\\)。流量不平衡看一段 <a href="/quant/event-time">事件时间</a> 窗口内主动买减主动卖，或买向增单减卖向增单。存量是状态，流量是状态的差分加成交。用存量去预测下一笔成交方向，与用流量去预测下一格中间价，识别条件不同。若再混入隐藏量与多档深度，同一个中文词可以指四五种随机变量。需要先锁定价位范围、是存量还是流量、分母如何归一，再谈它为什么可能预测价格。</p><h3 id="符号与尺度" tabindex="-1">符号与尺度 <a class="header-anchor" href="#符号与尺度" aria-label="Permalink to &quot;符号与尺度&quot;">​</a></h3><p>取最优档，\\(I_1=(q^b_1-q^a_1)/(q^b_1+q^a_1)\\in[-1,1]\\)。\\(I_1\\to 1\\) 表示买档相对厚。多档可把前 \\(K\\) 档量求和后再用同一公式，或对较远档位衰减加权。流量版本在窗口 \\(h\\) 内对带方向的事件求和，再除以活动总量。尺度都在 \\([-1,1]\\) 便于跨合约比较，但会掩盖绝对深度：两档都极薄时 \\(I_1\\) 仍可极端，此时它度量的是脆弱，不是大单压力。是否再用 \\(q^b+q^a\\) 做第二特征，属于同一问题的另一半：不平衡的形状与不平衡的规模。</p><p><span class="marginnote">微价格把中间价推向量薄一侧，本质上是把 \\(I_1\\) 嵌进价格读数。它与 \\(I_1\\) 高度相关，不是新的信息源。先选一个定义写进研究，不要同时把微价格变化和 \\(I_1\\) 当自变量还声称互相独立。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 L2 上，存量不平衡是各档聚合量的函数，计算廉价，丢失队内结构。在 L3 上，可以把队头若干量与队尾分开：队头厚更像即将被成交或被保护，队尾厚更像远处挂单。流量方面，需要事件标记：主动买成交、主动卖成交、买限价新增、卖限价新增、以及对应的撤销。一个可用的簿事件不平衡是：买侧新增减买侧撤销，减去卖侧的对应项，再减净主动买（主动买消耗卖侧深度）。它试图逼近「买向压力的净增量」，但对消息分类错误极度敏感。</p><p>窗口必须与问题匹配。下一笔成交方向，用当前快照 \\(I_1\\) 即可，不必再开五分钟窗。几分钟的中间价变化，用事件时间累积的流量更贴切，时钟五分钟会把爆发与空步等权。标准化方面，除以同期活动总量，比除以历史波动更少把波动率预测偷运进来——除非你明确要做的就是波动调整后的压力。截面上不同 tick、不同价格水平的合约，\\(I_1\\) 可比较，绝对量差不可直接比。</p><h3 id="与成交方向的分工" tabindex="-1">与成交方向的分工 <a class="header-anchor" href="#与成交方向的分工" aria-label="Permalink to &quot;与成交方向的分工&quot;">​</a></h3><p>成交方向不平衡（一段时间内主动买笔数或量减去主动卖）是流量的成交切片，不含未成交的挂撤。它更接近 Glosten-Milgrom 里「被观察到的交易方向」，因为信息模型的更新往往由成交触发。盘口存量不平衡可以在没有成交时就变——只因为一侧撤单。两者同时变厚时，通常是同向压力；两者背离时，例如买档很厚但主动成交全是卖，可能是冰山或暗池在另一侧成交，或显示深度正在被用作诱饵。方法上应报告两者的相关，而不是用其中一个名称覆盖另一个。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>在纯机械的一侧，不平衡改变下一次冲击的不对称。卖档薄，主动买更容易把 \\(a_1\\) 抬高，\\(m\\) 上升；买档薄则相反。即使所有主动单方向公平抛硬币，只要深度不对称，中间价的条件期望也会偏向薄的一侧。这不需要有人拥有关于价值的私有信息，只需要市价单沿现有几何消耗。Harris 所讲的深度与价格压力，首先是这种机制。</p><p>在信息的一侧，愿意把限价量暴露在某一侧、或把该侧撤空，本身可以是对价值的声明。知情者若确信价格将涨，可能在卖侧减少提供（以免被扫到便宜货），并在买侧排队或主动买。于是 \\(I_1\\) 变大与后续上涨同时出现，来源是信念而非几何。O&#39;Hara 的框架允许订单流作为信号；不平衡是订单流在簿上的截面投影。经验上短期预测力往往是两种机制的混合物：接下来几十毫秒到几秒，几何冲击占主导；稍长的窗口里，若不平衡持续，才更像信息或持续的需求。</p><h3 id="撤销如何让信号改号" tabindex="-1">撤销如何让信号改号 <a class="header-anchor" href="#撤销如何让信号改号" aria-label="Permalink to &quot;撤销如何让信号改号&quot;">​</a></h3><p>不平衡对撤单极敏感。知情者可以先在一侧堆量制造厚盘口，再在成交前撤走，留下一段被误读的 \\(I_1\\)。没有 L3 时，你无法知道厚的那一侧是稳定的队头还是随时可撤的队尾。冰山则让显示的 \\(q^a_1\\) 偏小，存量 \\(I_1\\) 偏向认为「卖侧薄、价格将涨」，而隐藏卖量正在等着吸收主动买。暗池成交不改明簿不平衡，却已经把部分需求消耗掉。机制边界因此很硬：不平衡是可见簿的统计量，它预测的是可见簿接下来如何被改写，不是不可见流动性的充分统计。</p><p><span class="marginnote">把不平衡当成 Kyle 里的总订单流 \\(y\\)，类型不匹配。Kyle 的 \\(y\\) 是提交给做市商的市价净需求；盘口 \\(I\\) 是限价存量的差。前者进入定价公式 \\(p=\\mu+\\lambda y\\)，后者进入冲击的不对称与限价供给。可以相关，不是同一个随机变量。</span></p>',20)),(e(),E(d,null,{default:t(()=>[B(i,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOB%5B%22%E4%B8%A4%E4%BE%A7%E5%8F%AF%E8%A7%81%E6%B7%B1%E5%BA%A6%22%5D%20--%3E%20I%5B%22%E5%AD%98%E9%87%8F%E4%B8%8D%E5%B9%B3%E8%A1%A1%20I%22%5D%0A%20%20OF%5B%22%E4%B8%BB%E5%8A%A8%E4%B9%B0%E5%87%8F%E4%B8%BB%E5%8A%A8%E5%8D%96%22%5D%20--%3E%20F%5B%22%E6%B5%81%E9%87%8F%E4%B8%8D%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20I%20--%3E%20G%5B%22%E5%87%A0%E4%BD%95%EF%BC%9A%E8%96%84%E4%BE%A7%E6%9B%B4%E6%98%93%E8%A2%AB%E6%89%93%E7%A9%BF%22%5D%0A%20%20F%20--%3E%20S%5B%22%E4%BF%A1%E5%8F%B7%EF%BC%9A%E6%96%B9%E5%90%91%E6%8C%81%E7%BB%AD%E7%9A%84%E9%9C%80%E6%B1%82%E6%88%96%E4%BF%A1%E6%81%AF%22%5D%0A%20%20G%20--%3E%20M%5B%22%E7%9F%AD%E6%97%B6%E4%B8%AD%E9%97%B4%E4%BB%B7%E6%BC%82%E7%A7%BB%22%5D%0A%20%20S%20--%3E%20M%0A%20%20CXL%5B%22%E6%92%A4%E5%8D%95%20%2F%20%E5%86%B0%E5%B1%B1%20%2F%20%E6%9A%97%E6%B1%A0%22%5D%20-.-%3E%7C%22%E6%B1%A1%E6%9F%93%E5%8F%AF%E8%A7%81%20I%22%7C%20I%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>定义必须先于回归。最优档与十档、存量与流量、是否包含增撤，会得到相关但不同的序列；把别人的系数抄到自己的 \\(I\\) 上没有意义。涨跌停、拍卖、极宽价差时 BBO 量的经济含义变化：停板上「买一」极厚并不预测下一 tick 上涨，因为价格暂时不能动。tick 较大时大量量堆在一档，\\(I_1\\) 变动慢；tick 较小时 \\(I_1\\) 抖动快，需要在事件时间上平滑，否则全是微观噪声。</p><p>预测力即使存在，也不等于可交易的边。吃掉薄侧会立刻改变 \\(I\\)，自己的市价单是不平衡的一部分，冲击成本可能大于信号收益。限价单用 \\(I\\) 决定挂哪一侧，改变的是排队与逆向选择，要用 <a href="/quant/cancel-queue-position">队列位置</a> 一起评估，不能只看中间价方向的命中率。多市场时本地 \\(I\\) 忽略他处流动性。任何把不平衡写成「因子」并与日频截面因子混用的做法，时间尺度已经离开微观结构，需要另做加总说明。</p><p><span class="marginnote">不要为不平衡编造一篇「经典论文」来撑腰。Harris 与 O&#39;Hara 提供的是深度、订单流与信息的语言；具体公式是你对可见簿的定义。经验系数属于你所用的层次与窗口，不属于一个放之四海的常数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>盘口不平衡是可见簿两侧量的标量摘要，须先声明档位、存量或流量、归一化方式。</li><li>存量描述冲击不对称的几何；流量更接近成交方向携带的信息；两者可背离。</li><li>即使主动方向随机，薄侧也更容易移动中间价；持续不平衡才更像需求或信息。</li><li>撤单、冰山与暗池污染可见 \\(I\\)；L2 分不清稳定队头与可撤队尾。</li><li>它不是 Kyle 的净市价流，也不是 Glosten-Milgrom 里那一笔成交方向本身。</li><li>定义、时段、tick、自成交冲击与跨市场流动性，构成预测力的边界。</li><li>出处：Harris, <em>Trading and Exchanges</em>；订单流作为信息见 O&#39;Hara, <em>Market Microstructure Theory</em>。</li></ul>',6))])}const I=l(p,[["render",h]]);export{b as __pageData,I as default};
